import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, join, relative, resolve } from "node:path";
import { getPlanChecklist, type PlanChecklist } from "./plan-checklist.js";

export type { PlanChecklist } from "./plan-checklist.js";
export { getPlanChecklist } from "./plan-checklist.js";

type BoulderWorkStatus = "active" | "paused" | "completed" | "abandoned";

type BoulderWork = {
	readonly activePlan: string;
	readonly planName: string;
	readonly status?: BoulderWorkStatus;
	readonly startedAt?: string;
	readonly updatedAt?: string;
	readonly sessionIds: readonly string[];
	readonly worktreePath?: string;
};

type BoulderState = {
	readonly works: readonly BoulderWork[];
	readonly mirrorWork: BoulderWork | null;
	readonly hasWorksMap: boolean;
};

export type ContinuationState = {
	readonly planName: string;
	readonly planPath: string;
	readonly boulderPath: string;
	readonly ledgerPath: string;
	readonly worktreePath: string | null;
	readonly checklist: PlanChecklist;
};

const SESSION_ID_PREFIX_PATTERN = /^(codex|opencode):/;

export function readContinuationState(cwd: string, sessionId: string): ContinuationState | null {
	const boulderPath = getBoulderFilePath(cwd);
	const boulderState = readBoulderState(boulderPath);
	if (boulderState === null) return null;

	const work = getWorkForSession(boulderState, normalizeSessionId(sessionId, "codex"));
	if (work === null || !isContinuableStatus(work.status)) return null;

	const planPath = resolveBoulderPlanPathForWork(cwd, work);
	const checklist = getPlanChecklist(planPath);
	if (checklist.total === 0) return null;

	return {
		planName: work.planName,
		planPath,
		boulderPath,
		ledgerPath: join(cwd, ".omo", "start-work", "ledger.jsonl"),
		worktreePath: work.worktreePath ?? null,
		checklist,
	};
}

function readBoulderState(path: string): BoulderState | null {
	try {
		const parsed: unknown = JSON.parse(readFileSync(path, "utf8"));
		return parseBoulderState(parsed);
	} catch (error) {
		if (error instanceof Error) return null;
		throw error;
	}
}

function parseBoulderState(value: unknown): BoulderState | null {
	if (!isRecord(value)) return null;

	const works: BoulderWork[] = [];
	const worksValue = value["works"];
	const hasWorksMap = isRecord(worksValue);
	if (hasWorksMap) {
		for (const workValue of Object.values(worksValue)) {
			const work = parseBoulderWork(workValue);
			if (work !== null) works.push(work);
		}
	}

	const mirrorWork = parseBoulderWork(value);
	if (works.length === 0 && mirrorWork === null) return null;
	return { works, mirrorWork, hasWorksMap };
}

function parseBoulderWork(value: unknown): BoulderWork | null {
	if (!isRecord(value)) return null;

	const activePlan = value["active_plan"];
	const planName = value["plan_name"];
	if (typeof activePlan !== "string") return null;

	const status = parseBoulderWorkStatus(value["status"]);
	const sessionIds = parseSessionIds(value["session_ids"]);
	const worktreePath = value["worktree_path"];
	const startedAt = value["started_at"];
	const updatedAt = value["updated_at"];

	return {
		activePlan,
		planName: typeof planName === "string" ? planName : activePlan,
		sessionIds,
		...(status === undefined ? {} : { status }),
		...(typeof startedAt === "string" ? { startedAt } : {}),
		...(typeof updatedAt === "string" ? { updatedAt } : {}),
		...(typeof worktreePath === "string" ? { worktreePath } : {}),
	};
}

function getWorkForSession(state: BoulderState, normalizedSessionId: string): BoulderWork | null {
	let newestWork: BoulderWork | null = null;
	let newestWorkMs = 0;

	for (const work of state.works) {
		if (!work.sessionIds.includes(normalizedSessionId)) continue;

		const workMs = parseIsoToMs(work.updatedAt ?? work.startedAt) ?? 0;
		if (newestWork === null || workMs > newestWorkMs) {
			newestWork = work;
			newestWorkMs = workMs;
		}
	}

	if (newestWork !== null) return newestWork;
	if (state.hasWorksMap) return null;
	if (state.mirrorWork?.sessionIds.includes(normalizedSessionId) === true) return state.mirrorWork;
	return null;
}

function resolveBoulderPlanPathForWork(cwd: string, work: BoulderWork): string {
	const absolutePlanPath = resolveTrackedPath(cwd, work.activePlan);
	const worktreePath = work.worktreePath?.trim();
	if (worktreePath === undefined || worktreePath.length === 0) return absolutePlanPath;

	const relativePlanPath = relative(resolve(cwd), absolutePlanPath);
	if (relativePlanPath.length === 0 || relativePlanPath.startsWith("..") || isAbsolute(relativePlanPath)) {
		return absolutePlanPath;
	}

	const worktreePlanPath = resolve(resolveTrackedPath(cwd, worktreePath), relativePlanPath);
	return existsSync(worktreePlanPath) ? worktreePlanPath : absolutePlanPath;
}

function resolveTrackedPath(baseDirectory: string, trackedPath: string): string {
	return isAbsolute(trackedPath) ? resolve(trackedPath) : resolve(baseDirectory, trackedPath);
}

function parseBoulderWorkStatus(value: unknown): BoulderWorkStatus | undefined {
	if (value === "active" || value === "paused" || value === "completed" || value === "abandoned") return value;
	return undefined;
}

function parseSessionIds(value: unknown): readonly string[] {
	if (!Array.isArray(value)) return [];
	const sessionIds: string[] = [];
	for (const item of value) {
		if (typeof item === "string") sessionIds.push(normalizeSessionId(item));
	}
	return sessionIds;
}

function normalizeSessionId(sessionId: string, platform: "codex" | "opencode" = "opencode"): string {
	if (SESSION_ID_PREFIX_PATTERN.test(sessionId)) return sessionId;
	return `${platform}:${sessionId}`;
}

function parseIsoToMs(value: string | undefined): number | null {
	if (value === undefined) return null;
	const parsed = Date.parse(value);
	return Number.isNaN(parsed) ? null : parsed;
}

function isContinuableStatus(status: BoulderWorkStatus | undefined): boolean {
	return status === "active" || status === "paused";
}

function getBoulderFilePath(cwd: string): string {
	return join(cwd, ".omo", "boulder.json");
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { stdin as processStdin, stdout as processStdout } from "node:process";

import { runStopHook } from "./codex-hook.js";
import type { ReadonlyFileSystem } from "./types.js";

const nodeFileSystem: ReadonlyFileSystem = {
	readFileSync(path, encoding) {
		return readFileSync(path, encoding);
	},
};

const command = process.argv[2];
const subcommand = process.argv[3];

if (command === "hook" && (subcommand === "stop" || subcommand === "subagent-stop")) {
	await runHookCli();
} else {
	process.stderr.write("Usage: omo-start-work-continuation hook <stop|subagent-stop>\n");
	process.exitCode = 1;
}

async function runHookCli(): Promise<void> {
	const raw = await readStdin();
	if (raw.trim().length === 0) return;
	const parsed = parseHookInput(raw);
	const output = runStopHook(parsed, nodeFileSystem);
	if (output.length > 0) processStdout.write(output);
}

function parseHookInput(raw: string): unknown | undefined {
	try {
		const parsed: unknown = JSON.parse(raw);
		return parsed;
	} catch (error) {
		if (error instanceof SyntaxError) return undefined;
		throw error;
	}
}

function readStdin(): Promise<string> {
	return new Promise((resolve) => {
		let data = "";
		processStdin.setEncoding("utf8");
		processStdin.on("data", (chunk: string) => {
			data += chunk;
		});
		processStdin.once("error", () => resolve(data));
		processStdin.once("end", () => resolve(data));
	});
}

import type { ContinuationState } from "./boulder-reader.js";
import { readContinuationState } from "./boulder-reader.js";
import { START_WORK_CONTINUATION_DIRECTIVE } from "./directive.js";
import type { ReadonlyFileSystem, StopHookEventName, StopHookOutput, StopInput } from "./types.js";

export function runStopHook(input: unknown, fs: ReadonlyFileSystem): string {
	if (!isStopInput(input)) return "";
	if (input.stop_hook_active) return "";
	if (hasAllowedExternalBlockerMarker(input.last_assistant_message)) return "";
	if (transcriptHasContextPressureMarker(input.transcript_path, fs)) return "";
	const state = readContinuationState(input.cwd, input.session_id);
	if (state === null) return "";
	return JSON.stringify({
		decision: "block",
		reason: renderDirective(state, input.session_id),
	} satisfies StopHookOutput);
}

function renderDirective(state: ContinuationState, sessionId: string): string {
	const lineBreak = String.fromCharCode(10);
	const worktreeBlock =
		state.worktreePath === null
			? ""
			: `${lineBreak}- Worktree: \`${state.worktreePath}\` (all edits, tests, and commands run inside this directory)`;
	const replacements = {
		PLAN_NAME: state.planName,
		PLAN_PATH: state.planPath,
		BOULDER_PATH: state.boulderPath,
		REMAINING_COUNT: String(state.checklist.remaining),
		TOTAL_COUNT: String(state.checklist.total),
		NEXT_TASK_LABEL: state.checklist.nextTaskLabel ?? "none (final gate pending)",
		WORKTREE_BLOCK: worktreeBlock,
		LEDGER_PATH: state.ledgerPath,
		SESSION_ID: sessionId,
	} as const;
	let rendered = START_WORK_CONTINUATION_DIRECTIVE;
	for (const [placeholder, value] of Object.entries(replacements)) {
		rendered = rendered.replaceAll(`{{${placeholder}}}`, value);
	}
	return rendered;
}

const EXTERNAL_BLOCKER_MARKER = "<start-work-blocked-external>";
const ULTRAWORK_OPENER = "ULTRAWORK MODE ENABLED!";

// The marker alone is not enough to end the turn. `directive.md` requires the exact blocker and
// the condition that resumes the work on the following lines, so at least one is required here
// too. That keeps a bare echo of the marker, whether quoted back from a prompt or produced by
// untrusted text the agent read, from skipping the continuation guard.
function hasAllowedExternalBlockerMarker(lastAssistantMessage: string | undefined): boolean {
	if (lastAssistantMessage === undefined) return false;
	const lines = lastAssistantMessage.split(String.fromCharCode(10));
	const [firstLine = "", secondLine = ""] = lines;

	let markerLineIndex = -1;
	if (firstLine.trim() === EXTERNAL_BLOCKER_MARKER) markerLineIndex = 0;
	else if (firstLine.trim() === ULTRAWORK_OPENER && secondLine.trim() === EXTERNAL_BLOCKER_MARKER) markerLineIndex = 1;
	if (markerLineIndex === -1) return false;

	return lines.slice(markerLineIndex + 1).some((line) => line.trim() !== "");
}

const CONTEXT_PRESSURE_MARKERS = [
	"context compacted",
	"context_length_exceeded",
	"skill descriptions were shortened",
	"context_too_large",
	"codex ran out of room in the model's context window",
	"your input exceeds the context window",
	"long threads and multiple compactions",
] as const;

function transcriptHasContextPressureMarker(transcriptPath: string, fs: ReadonlyFileSystem): boolean {
	try {
		const transcript = fs.readFileSync(transcriptPath, "utf8").toLowerCase();
		return CONTEXT_PRESSURE_MARKERS.some((marker) => transcript.includes(marker));
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function isStopInput(value: unknown): value is StopInput {
	return (
		isRecord(value) &&
		isStopHookEventName(value["hook_event_name"]) &&
		typeof value["session_id"] === "string" &&
		typeof value["turn_id"] === "string" &&
		typeof value["transcript_path"] === "string" &&
		typeof value["cwd"] === "string" &&
		typeof value["model"] === "string" &&
		typeof value["permission_mode"] === "string" &&
		typeof value["stop_hook_active"] === "boolean" &&
		optionalString(value["last_assistant_message"])
	);
}

function isStopHookEventName(value: unknown): value is StopHookEventName {
	return value === "Stop" || value === "SubagentStop";
}

function optionalString(value: unknown): boolean {
	return value === undefined || typeof value === "string";
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { readFileSync } from "node:fs";

export const START_WORK_CONTINUATION_DIRECTIVE: string = readFileSync(
	new URL("../directive.md", import.meta.url),
	"utf8",
);

export type { ContinuationState, PlanChecklist } from "./boulder-reader.js";
export { readContinuationState } from "./boulder-reader.js";
export { runStopHook } from "./codex-hook.js";
export { START_WORK_CONTINUATION_DIRECTIVE } from "./directive.js";
export type { ReadonlyFileSystem, StopHookEventName, StopHookOutput, StopInput } from "./types.js";

import { existsSync, readFileSync } from "node:fs";

export type PlanChecklist = {
	readonly completed: number;
	readonly remaining: number;
	readonly total: number;
	readonly nextTaskLabel: string | null;
};

const TODO_HEADING_PATTERN = /^##[ \t]+TODOs(?:[ \t]+#+)?[ \t]*$/i;
const FINAL_VERIFICATION_HEADING_PATTERN = /^##[ \t]+Final Verification Wave(?:[ \t]+#+)?[ \t]*$/i;
const SECTION_BOUNDARY_HEADING_PATTERN = /^#{1,2}(?:[ \t]+|$)/;
const FENCE_PATTERN = /^[ \t]{0,3}(`{3,}|~{3,})(.*)$/;
const SIMPLE_CHECKBOX_PATTERN = /^[-*][ \t]*\[[ \t]*([xX]?)[ \t]*\][ \t]+(.+)$/;
const TODO_CHECKBOX_PATTERN = /^- \[([ xX])\] ([1-9]\d*\. .+)$/;
const FINAL_WAVE_CHECKBOX_PATTERN = /^- \[([ xX])\] (F[1-9]\d*\. .+)$/i;

type ChecklistSection = "todo" | "final-wave" | "other";

type ParsedCheckbox = {
	readonly checked: boolean;
	readonly label: string;
};

type MarkdownFence = {
	readonly marker: "`" | "~";
	readonly length: number;
};

export function getPlanChecklist(planPath: string): PlanChecklist {
	if (!existsSync(planPath)) return emptyChecklist();

	try {
		return parsePlanChecklist(readFileSync(planPath, "utf8"));
	} catch (error) {
		if (error instanceof Error) return emptyChecklist();
		throw error;
	}
}

export function parsePlanChecklist(markdown: string): PlanChecklist {
	const lines = markdown.split(/\r?\n/);
	if (!hasStructuredSection(lines)) return parseSimpleChecklist(lines);

	let completed = 0;
	let remaining = 0;
	let nextTaskLabel: string | null = null;
	let section: ChecklistSection = "other";
	let fence: MarkdownFence | null = null;

	for (const line of lines) {
		if (fence !== null) {
			if (isClosingFence(line, fence)) fence = null;
			continue;
		}
		const openingFence = parseOpeningFence(line);
		if (openingFence !== null) {
			fence = openingFence;
			continue;
		}

		if (SECTION_BOUNDARY_HEADING_PATTERN.test(line)) {
			section = parseStructuredSectionHeading(line);
			continue;
		}
		if (section === "other") continue;

		const checkbox = parseStructuredCheckbox(line, section);
		if (checkbox === null) continue;
		if (checkbox.checked) completed += 1;
		else {
			remaining += 1;
			nextTaskLabel = nextTaskLabel ?? checkbox.label;
		}
	}

	return { completed, remaining, total: completed + remaining, nextTaskLabel };
}

function hasStructuredSection(lines: readonly string[]): boolean {
	let fence: MarkdownFence | null = null;
	for (const line of lines) {
		if (fence !== null) {
			if (isClosingFence(line, fence)) fence = null;
			continue;
		}
		const openingFence = parseOpeningFence(line);
		if (openingFence !== null) {
			fence = openingFence;
			continue;
		}
		if (parseStructuredSectionHeading(line) !== "other") return true;
	}
	return false;
}

function parseSimpleChecklist(lines: readonly string[]): PlanChecklist {
	let completed = 0;
	let remaining = 0;
	let nextTaskLabel: string | null = null;
	let fence: MarkdownFence | null = null;

	for (const line of lines) {
		if (fence !== null) {
			if (isClosingFence(line, fence)) fence = null;
			continue;
		}
		const openingFence = parseOpeningFence(line);
		if (openingFence !== null) {
			fence = openingFence;
			continue;
		}

		const checkbox = parseSimpleTopLevelCheckbox(line);
		if (checkbox === null) continue;
		if (checkbox.checked) completed += 1;
		else {
			remaining += 1;
			nextTaskLabel = nextTaskLabel ?? checkbox.label;
		}
	}

	return { completed, remaining, total: completed + remaining, nextTaskLabel };
}

function parseStructuredSectionHeading(line: string): ChecklistSection {
	if (TODO_HEADING_PATTERN.test(line)) return "todo";
	if (FINAL_VERIFICATION_HEADING_PATTERN.test(line)) return "final-wave";
	return "other";
}

function parseStructuredCheckbox(line: string, section: "todo" | "final-wave"): ParsedCheckbox | null {
	const pattern = section === "todo" ? TODO_CHECKBOX_PATTERN : FINAL_WAVE_CHECKBOX_PATTERN;
	const match = line.match(pattern);
	const marker = match?.[1];
	const label = match?.[2];
	if (marker === undefined || label === undefined) return null;
	return { checked: marker.toLowerCase() === "x", label };
}

function parseSimpleTopLevelCheckbox(line: string): ParsedCheckbox | null {
	const match = line.match(SIMPLE_CHECKBOX_PATTERN);
	const marker = match?.[1];
	const label = match?.[2];
	if (marker === undefined || label === undefined) return null;
	return { checked: marker.toLowerCase() === "x", label };
}

function parseOpeningFence(line: string): MarkdownFence | null {
	const match = line.match(FENCE_PATTERN);
	const run = match?.[1];
	const info = match?.[2];
	const marker = run?.charAt(0);
	if (
		run === undefined ||
		info === undefined ||
		(marker !== "`" && marker !== "~") ||
		(marker === "`" && info.includes("`"))
	)
		return null;
	return { marker, length: run.length };
}

function isClosingFence(line: string, fence: MarkdownFence): boolean {
	const run = line.match(/^[ \t]{0,3}(`{3,}|~{3,})[ \t]*$/)?.[1];
	return run?.charAt(0) === fence.marker && run.length >= fence.length;
}

function emptyChecklist(): PlanChecklist {
	return { completed: 0, remaining: 0, total: 0, nextTaskLabel: null };
}

export const STOP_HOOK_EVENTS = ["Stop", "SubagentStop"] as const;
export type StopHookEventName = (typeof STOP_HOOK_EVENTS)[number];

export type StopInput = {
	readonly hook_event_name: StopHookEventName;
	readonly session_id: string;
	readonly turn_id: string;
	readonly transcript_path: string;
	readonly cwd: string;
	readonly model: string;
	readonly permission_mode: string;
	readonly stop_hook_active: boolean;
	readonly last_assistant_message?: string;
};

export type StopHookOutput = {
	readonly decision: "block";
	readonly reason: string;
};

export type ReadonlyFileSystem = {
	readFileSync(path: string, encoding: "utf8"): string;
};

import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { getPlanChecklist, readContinuationState } from "../src/boulder-reader.js";

const cleanupRoots: string[] = [];
const SCAFFOLD_PLAN_MARKDOWN = readFileSync(new URL("./fixtures/plan-scaffold.md", import.meta.url), "utf8");

afterEach(() => {
	for (const root of cleanupRoots.splice(0)) rmSync(root, { recursive: true, force: true });
});

describe("start-work plan checklist consumption", () => {
	it("#given scaffold headings and canonical numbered rows #when parsed #then structured totals and next label match", () => {
		// given
		const planPath = createPlan(SCAFFOLD_PLAN_MARKDOWN);

		// when
		const checklist = getPlanChecklist(planPath);

		// then
		expect(checklist).toEqual({
			completed: 2,
			remaining: 2,
			total: 4,
			nextTaskLabel: "1. Implement checklist parser parity",
		});
	});

	it("#given nested checkboxes #when parsed #then ignores non-column-zero items", () => {
		// given
		const planPath = createPlan(
			["## TODOs", "- [ ] 1. Top-level", "  - [ ] Nested", "\t- [ ] Tab nested", "- [x] 2. Complete"].join("\n"),
